#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>a(n);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
vector<int>st;long long res=0;
for(int i=0;i<n;++i){
while(!st.empty()&&a[st.back()]<a[i]){
int mid=st.back();st.pop_back();
if(st.empty())break;
long long h=min(a[st.back()],a[i])-a[mid];
long long w=i-st.back()-1;
res+=h*w;}
st.push_back(i);}
printf("%lld\n",res);return 0;}

